import React, { useState } from 'react';
import { Table, Button, Input, Space, Tag } from 'antd';
import { EditOutlined, DeleteOutlined, PlusOutlined, SearchOutlined } from '@ant-design/icons';
import { Modal } from 'antd';
import AddLoaiSanPham from './AddLoaiSanPham';
const { Search } = Input;

interface LoaiSanPham {
    id: number;
    tenloai: string;
    mota: string;
}

const dataSource: LoaiSanPham[] = [
    { id: 1, tenloai: 'Đồ uống', mota: 'Đồ uống có ga' },
    { id: 2, tenloai: 'Đồ ăn vặt', mota: 'Đồ ăn nhẹ, ăn kèm' },
    { id: 3, tenloai: 'Kem', mota: 'Kem tươi mát lạnh' },
    { id: 4, tenloai: 'Cà phê', mota: 'Coffe nguyên chất' },
    { id: 5, tenloai: 'Trà sữa', mota: 'Trà sữa béo ngậy' },
];

// Cấu hình các cột cho Table
const columns = [
    {
        title: 'ID',
        dataIndex: 'id',
        key: 'id',
        width: 80,
    },
    {
        title: 'Tên loại',
        dataIndex: 'tenloai',
        key: 'ten_loai',
    },
    {
        title: 'Mô tả',
        dataIndex: 'mota',
        key: 'mo_ta',
    },
    {
        title: 'Chức năng',
        key: 'action',
        width: 150,
        render: (_: any, record: LoaiSanPham) => (
            <Space size="small">
                <Button
                    type="primary"
                    style={{ backgroundColor: '#333', borderColor: '#333' }}
                    size="small"
                >
                    Sửa
                </Button>
                <Button
                    type="primary"
                    danger
                    size="small"
                >
                    Xóa
                </Button>
            </Space>
        ),
    },
];

const DSLoaiSanPham: React.FC = () => {

    const onSearch = (value: string) => {
        console.log('Đang tìm kiếm:', value);

    };

    const [isModalOpen, setIsModalOpen] = useState(false);

    const handleAdd = () => {
        setIsModalOpen(true);
    };

    const handleCancel = () => {
        setIsModalOpen(false);
    };

    return (
        <div style={{ padding: 0 }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 20 }}>
                <h2>Quản lý Loại sản phẩm</h2>
                <Button
                    type="primary"
                    icon={<PlusOutlined />}
                    onClick={handleAdd}
                >
                    Thêm Loại sản phẩm
                </Button>
            </div>

            <Modal
                title="Thêm Loại sản phẩm mới"
                open={isModalOpen}
                onCancel={handleCancel}
                footer={null}
            >
                <AddLoaiSanPham /> {/* Render form bên trong Modal */}
            </Modal>

            {/* 1. Thanh tìm kiếm */}
            <div style={{ marginBottom: 20 }}>
                <Search
                    placeholder="Tên loại sản phẩm cần tìm"
                    allowClear
                    enterButton={<SearchOutlined />}
                    onSearch={onSearch}
                    style={{ maxWidth: 400 }}
                />
            </div>

            {/* 2. Bảng hiển thị danh sách */}
            <Table
                pagination={{
                    position: ['bottomCenter'],
                    pageSize: 10,
                    showSizeChanger: false,
                    total: dataSource.length,
                    showTotal: (total, range) => `${range[0]}-${range[1]} trên tổng ${total} mục`,
                }}
                dataSource={dataSource}
                columns={columns}
                rowKey="id"
            />
        </div>
    );
};

export default DSLoaiSanPham;
